import json,re,pandas as pd
def nodup(p):
  d={}
  for k,v in p:
    assert k not in d; d[k]=v
  return d
doc=json.load(open('salida/resultado.json'),object_pairs_hook=nodup)
assert list(doc)==['version','identidad','filas'] and doc['version']==3
s=pd.read_csv('paquete/esquema-identidades.tsv',sep='\t',dtype=str,keep_default_na=False)
assert [f['llave'] for f in doc['filas']]==s.llave.tolist() and [f['unidad'] for f in doc['filas']]==s.unidad.tolist()
dec=re.compile(r'^-?\d+(\.\d+)?([eE][-+]?\d+)?$')
from collections import Counter; c=Counter()
for f in doc['filas']:
  if f['estado']=='RECONSTRUIDO':
    assert dec.match(f['punto']); c[f['estado_ic']]+=1
    if f['estado_ic']=='CALCULADO': assert float(f['ic95_inf'])<=float(f['punto'])<=float(f['ic95_sup'])
  else: assert f.get('motivo') and not any(k in f for k in ('punto','ic95_inf','ic95_sup','estado_ic'))
print('OK',c)
t=pd.read_csv('salida/diagnosticos-ic-v1.tsv',sep='\t',dtype=str); print(t.shape, t.columns.tolist()[:3]); print(t.tipo_incertidumbre.value_counts().to_dict()); print(t.n_replicas_no_estimables.value_counts().to_dict())
d=json.load(open('salida/diagnostico.json')); print(json.dumps(d['datos'],ensure_ascii=False))
print(Counter(l['publicabilidad'] for l in d['llaves']))
x=[l for l in d['llaves'] if l['conducta']=='depresion-cesd7' and l['eje'] in('TOTAL','EDAD')][:2]; print(json.dumps(x,ensure_ascii=False))
"

